def is_possible(nums):
    from collections import Counter
    count = Counter(nums)
    ends = Counter()                                          # how many subsequences currently end at each value

    for num in nums:
        if count[num] == 0:
            continue                                                # already placed
        count[num] -= 1
        appended = False
        for candidate_end in [num - 1]:                              # scan for an appendable subsequence
            if ends[candidate_end] > 0:
                ends[candidate_end] -= 1
                ends[num] += 1
                appended = True
        if not appended:
            if count[num + 1] > 0 and count[num + 2] > 0:
                count[num + 1] -= 1
                count[num + 2] -= 1
                ends[num + 2] += 1
            else:
                return False
    return True


if __name__ == "__main__":
    print(is_possible([1, 2, 3, 3, 4, 5]))

