import java.util.*;

public class Main {
    boolean isPossible(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int num : nums) count.put(num, count.getOrDefault(num, 0) + 1);
        Map<Integer, Integer> ends = new HashMap<>();                   // how many subsequences currently end at each value

        for (int num : nums) {
            if (count.get(num) == 0) continue;
            count.put(num, count.get(num) - 1);
            boolean appended = false;
            if (ends.getOrDefault(num - 1, 0) > 0) {                        // check for an appendable subsequence
                ends.put(num - 1, ends.get(num - 1) - 1);
                ends.put(num, ends.getOrDefault(num, 0) + 1);
                appended = true;
            }
            if (!appended) {
                if (count.getOrDefault(num + 1, 0) > 0 && count.getOrDefault(num + 2, 0) > 0) {
                    count.put(num + 1, count.get(num + 1) - 1);
                    count.put(num + 2, count.get(num + 2) - 1);
                    ends.put(num + 2, ends.getOrDefault(num + 2, 0) + 1);
                } else {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.isPossible(new int[]{1, 2, 3, 3, 4, 5}));
    }
}

