#include <bits/stdc++.h>
using namespace std;

bool isPossible(vector<int>& nums) {
    unordered_map<int, int> count, ends;                                 // ends: how many subsequences end at each value
    for (int num : nums) count[num]++;

    for (int num : nums) {
        if (count[num] == 0) continue;
        count[num]--;
        bool appended = false;
        if (ends[num - 1] > 0) {                                             // check for an appendable subsequence
            ends[num - 1]--;
            ends[num]++;
            appended = true;
        }
        if (!appended) {
            if (count[num + 1] > 0 && count[num + 2] > 0) {
                count[num + 1]--;
                count[num + 2]--;
                ends[num + 2]++;
            } else {
                return false;
            }
        }
    }
    return true;
}

int main() {
    vector<int> nums = {1, 2, 3, 3, 4, 5};
    cout << (isPossible(nums) ? "true" : "false") << endl;
    return 0;
}

