public class Main {
    boolean isPossible(int[] nums) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int num : nums) count.merge(num, 1, Integer::sum);
        Map<Integer, Integer> ends = new HashMap<>();                    // subsequences currently ending at each value

        for (int num : nums) {
            if (count.get(num) == 0) continue;
            count.merge(num, -1, Integer::sum);
            if (ends.getOrDefault(num - 1, 0) > 0) {
                ends.merge(num - 1, -1, Integer::sum);
