                count.merge(num + 1, -1, Integer::sum);
                count.merge(num + 2, -1, Integer::sum);
                ends.merge(num + 2, 1, Integer::sum);                          // start a brand new subsequence of length 3
            } else {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.isPossible(new int[]{1, 2, 3, 3, 4, 5}));
